  Stage_118134_Name = {
    Text = "Göttliche Mutter-Ferien"
  },
  Stage_118135_Desc = {
    Text = "Mühelos im Wirbelkritischen umherirren, nur ein Trugbild des zerbrechlichen Schiffs.\nIn den mit bloßem Auge unsichtbaren Strömungen verbirgt sich eine gewaltige Sogkraft, die alle Glücksritter verschlingen und ersticken kann."
  },
  Stage_118135_Name = {Text = "Wirbel"},
  Stage_118136_Desc = {
