  Stage_118138_Name = {
    Text = "Außenstehender"
  },
  Stage_118139_Desc = {
    Text = "Die Heilige steht hoch oben auf dem Altar und blickt auf die lodernden Flammen hinunter.\nDie züngelnde Flamme spiegelt in ihren Augen nicht Angst wider, sondern das endlich kommende Schicksal.\nSie kann das Knistern des brennenden Holzes hören und das Echo der schwindenden Prophezeiung in ihrem Inneren.\nIn diesem Moment ist sie nicht mehr der gefesselte Gefangene."
  },
  Stage_118139_Name = {
    Text = "Lotsenzeremonie"
  },
  Stage_118140_Desc = {
    Text = "Der Ritter rüstet sein Pferd, zieht seine Rüstung an und schlägt auf den heranrasenden Windmühlen ein."
  },
  Stage_118140_Name = {
    Text = "Windradritter"
  },
  Stage_118141_Desc = {
