  Stage_122601_Name = {
    Text = "Mouchette Level"
  },
  Stage_123112_Desc = {
    Text = "Der Nebel verdeckte meine Augen und trennte mich von meiner eigenen Welt, aber durch deinen Blick sah ich die Vergangenheit, zu der ich niemals zurückkehren kann, die Menschen, die ich niemals wiedersehen kann.\nWir sind ähnlich."
  },
  Stage_123112_Name = {
    Text = "Durch deinen Blick"
  },
  Stage_123113_Desc = {
    Text = "Der Nebel verdeckte meine Augen und trennte mich von meiner eigenen Welt, aber durch deinen Blick sah ich die Vergangenheit, zu der ich niemals zurückkehren kann, die Menschen, die ich niemals wiedersehen kann.\nWir sind ähnlich."
  },
  Stage_123113_Name = {
    Text = "Durch deinen Blick"
  },
  Stage_125199_Desc = {
    Text = "Nur der Käfer, der sich in die Liebe hineinsteigert, kann so zerbrechlich, so widerstandsfähig, so lächerlich und doch so außergewöhnlich sein. \n Oh mein Gott, komm mit mir, um etwas noch Wundervolleres zu sehen; ihr werdet aufeinander achten, und von jetzt an werdet ihr eng verbunden sein."
  },
  Stage_125199_Name = {
    Text = "Seidene Falle: Teil III"
  },
  Stage_125200_Desc = {
    Text = "Leidenschaft hat immer ihr Ziel, führt nicht immer dazu, gemeinsam alt zu werden, sondern vielleicht häufiger zu einem ungerechten Tod. \n Manchmal ist es die Liebe, die einen ungerechten Tod findet, und manchmal bist du es."
  },
  Stage_125200_Name = {
    Text = "Ungerechter Tod: Wahnsinn"
  },
  Stage_125201_Desc = {
    Text = "Deine alte Liebe hat dich verlassen; warum bereust du erst jetzt? \n Hehe, es ist nicht zu spät, keine Eile, schau—mein Herr. Solange die Sonne untergeht, wird jede Lampe, jede rote Kerze ihre Gestalt und ihren Schatten hinter dem Fenster werfen."
  },
  Stage_125201_Name = {
    Text = "Schatten Dahinter: Teil II"
  },
  Stage_125202_Desc = {
    Text = "„... wie die Zikade ihre Haut ablegt und sich verwandelt, nennt man Leichenschau und den Aufstieg zum Unsterblichen...\"\nOh, das ist eigentlich nicht so, das ist eine absurde Legende, aber was macht das schon? Sie beten mit Blut und Tränen, und so erwacht die erschreckende Schönheit und Angst aus ihr."
  },
  Stage_125202_Name = {
    Text = "Leichnamaufstieg: VI"
  },
  Stage_125203_Desc = {
    Text = "Deine alte Liebe hat dich verlassen; warum bereust du erst jetzt? \n Hehe, es ist nicht zu spät, keine Eile, schau—mein Herr. Solange die Sonne untergeht, wird jede Lampe, jede rote Kerze ihre Gestalt und ihren Schatten hinter dem Fenster werfen."
  },
  Stage_125203_Name = {
    Text = "Schatten Hinter: Ich"
  },
  Stage_125204_Desc = {
    Text = "Sie knien gemeinsam unter dem Räucheraltar, die formlos mysteriöse Göttin, unbegreiflich, undefinierbar und unanfechtbar. \n Alles opfernd, allem gefügend, aufsteigend zur einen Euphorie, dem ewigen Chaos."
  },
  Stage_125204_Name = {
    Text = "Euphorie: Wahnsinn"
  },
  Stage_125205_Desc = {
    Text = "Ich mag deinen Duft, und ich werde für dich deinen Feind kosten."
  },
  Stage_125205_Name = {
    Text = "Die Spur des Duftes: Teil II"
  },
  Stage_125206_Desc = {
    Text = "Dieser mysteriöse Kult schwebt jenseits der historischen Aufzeichnungen der alten östlichen Nation, unerkennbar und undefinierbar. Nur sehr wenige Individuen, die noch nicht gestorben sind und ewig im Land der Traumlosen verweilen, haben einst den Namen der Gottheit gekannt, die sie verehrten. \n Sie wird genannt—\"@4\""
  },
  Stage_125206_Name = {
    Text = "Orden der Schwellungsgnade: I"
  },
  Stage_125207_Desc = {
    Text = "Sie knien gemeinsam unter dem Räucheraltar, die formlos mysteriöse Göttin, unbegreiflich, undefinierbar und unanfechtbar. \n Alles opfernd, allem gefügend, aufsteigend zur einen Euphorie, dem ewigen Chaos."
  },
