  Stage_129500_Desc = {
    Text = "Jedes Jahreswechsel Fest im Steinernen Drachenreich, egal woher man kommt, versammeln sich die Familien. \n Sie besteigen den Zug in die Ferne, während das Jahreswechsel Fest naht, und halten mit sehnsüchtigen Herzen Ausschau nach dem Moment des lang erwarteten Wiedersehens."
  },
  Stage_129500_Name = {
    Text = "Wunschjahreszug"
  },
  Stage_129501_Desc = {
    Text = "Keine Angst, das ist nur ein Spiel. \n Ein grausames, bösartiges Spiel."
  },
  Stage_129501_Name = {
    Text = "Das Spiel beginnt"
  },
  Stage_129502_Desc = {
    Text = "Hör nicht auf, weiche nicht zurück. \n Wenn die wohlwollenden Menschen ihre Waffen niederlegen, wird das Böse die Gelegenheit nutzen, um weiterzumachen."
  },
  Stage_129502_Name = {
    Text = "Der zweite Tote"
  },
  Stage_129503_Desc = {
    Text = "Ist das der absolute Gegenangriff der Gerechtigkeit...?"
  },
  Stage_129503_Name = {
    Text = "Versteckter Finishing Move"
  },
  Stage_129504_Desc = {
    Text = "Der Hebel taucht oft in deinen Träumen auf. \n Soll ich ihn drücken oder ziehen? Das ist die Frage."
  },
  Stage_129504_Name = {
    Text = "Dunkler Raum"
  },
  Stage_129505_Desc = {
    Text = "Feuerwerk verabschiedet das alte Jahr, die vergangenen Tage sind in der Asche nicht mehr zu verfolgen."
