  Stage_139577_Desc = {
    Text = "Großartig, diese... nein nein nein, ich meine, diese schwarzen Katzen sind absolut schrecklich!"
  },
  Stage_139577_Name = {
    Text = "Schwarzer Goldrausch"
  },
  Stage_139578_Desc = {
    Text = "Die Taschen voller Silberkern und Rosenskript, kehrt der siegreiche General beladen mit Beute nach Hause zurück."
  },
  Stage_139578_Name = {
    Text = "Rückkehr mit voller Ladung"
  },
  Stage_139579_Desc = {
    Text = "Du hast es auf die größte Katze von allen abgesehen. Und sie hat es auf dich abgesehen."
  },
  Stage_139579_Name = {
    Text = "Größte Katze"
  },
  Stage_139580_Desc = {
    Text = "Aber es gibt noch so viele Katzen. Lass uns gehen... ein letztes Mal?"
  },
  Stage_139580_Name = {
    Text = "Noch einmal"
  },
  Stage_139581_Desc = {
    Text = "Als das erste Schimmern von Silber über das pechschwarze Meer leuchtet, schwingt dein Katzenfangnetz mit erneuter Kraft."
  },
  Stage_139581_Name = {
    Text = "Erster Eimer Silber"
  },
  Stage_139582_Desc = {
    Text = "Die schwarzen Katzen wehren sich — das bedeutet, du machst etwas richtig."
  },
  Stage_139582_Name = {
    Text = "Widerstand gegen die Festnahme"
  },
  Stage_139583_Desc = {
    Text = "Größeres Netz, mehr Katzen — und die großen brauchen ein großes Netz. Holt sie rein!"
  },
  Stage_139583_Name = {
    Text = "Holt sie rein!"
  },
  Stage_140299_Desc = {
    Text = "Erblühe und tanze.\nDu hast beschlossen, dass du ihre Hand niemals loslassen wirst, egal wie gefährlich der Weg vor dir ist.\nIm Moment unseres Abschieds soll die verkehrte Welt mit „wahr\" erfüllt sein."
  },
  Stage_140299_Name = {Text = "Abschied"},
  Stage_140300_Desc = {
    Text = "Das Gedächtnis ist wie ein Samen, der alles in sich trägt, aber geheim bleibt. \n Erst wenn er bewässert wird, Wurzeln schlägt und sprießt, akzeptiert und umarmt ihn die Erde und erlaubt ihm, Kraft aus der Realität zu schöpfen."
  },
  Stage_140300_Name = {
