  Stage_144353_Name = {
    Text = "Temporärer Text"
  },
  Stage_145312_Desc = {
    Text = "Willkommen! Willkommen in der Arena des Astralen Cetus! Willkommen in dieser Halle des Gemetzels!\nGenerale, Assassinen, Kopfgeldjäger, Gladiatoren... alle lebenden Legenden versammeln sich hier.\nKämpfe, verbünde dich, verrate – nutze alle dir zur Verfügung stehenden Mittel, Überlebender.\nEs gibt nur eine Regel: Nur der Letzte, der noch steht, darf jene Tür aufstoßen."
  },
  Stage_145312_Name = {
    Text = "Halle des Gemetzels: IV"
  },
  Stage_145313_Desc = {
    Text = "Ehre, Gerechtigkeit, Würde... bloße Ketten, die sich die Schwachen selbst schmieden.\nSie hungert nur nach dem, was stärker ist. In dieser blutgetränkten Arena gibt es vielleicht nur noch einen, der ihrer Beachtung würdig ist."
  },
  Stage_145313_Name = {
    Text = "Der dritte Abschnitt"
  },
  Stage_145314_Desc = {
    Text = "Der Weg, den Astralen Cetus zu erfreuen, ist einfach: genug Blut, genug Stärke, genug Verlangen...\nWenn du über unzählige Leichen hinweggetrampelt bist, herzlichen Glückwunsch. Du hast das Recht verdient, an diesem Wettkampf teilzunehmen."
  },
  Stage_145314_Name = {
    Text = "Das Opfer·III"
  },
  Stage_145315_Desc = {
    Text = "Willkommen! Willkommen in der Arena des Astralen Cetus! Willkommen in dieser Halle des Gemetzels!\nGenerale, Assassinen, Kopfgeldjäger, Gladiatoren... alle lebenden Legenden versammeln sich hier.\nKämpfe, verbünde dich, verrate – nutze alle dir zur Verfügung stehenden Mittel, Überlebender.\nEs gibt nur eine Regel: Nur der Letzte, der noch steht, darf jene Tür aufstoßen."
  },
  Stage_145315_Name = {
    Text = "Halle des Gemetzels: III"
  },
  Stage_145316_Desc = {
    Text = "Der Weg, den Astralen Cetus zu erfreuen, ist einfach: genug Blut, genug Stärke, genug Verlangen...\nWenn du über unzählige Leichen hinweggetrampelt bist, herzlichen Glückwunsch. Du hast das Recht verdient, an diesem Wettkampf teilzunehmen."
  },
  Stage_145316_Name = {
    Text = "Das Opfer·eins"
  },
  Stage_145317_Desc = {
    Text = "Von all den Gefahren hier sind die wilden Tiere die harmlosesten."
  },
  Stage_145317_Name = {
    Text = "Käfigbestie· fünf"
  },
  Stage_145318_Desc = {
    Text = "Endlich hast du alles, was du dir je gewünscht hast: Stärke, Reichtum, Ruhm und grenzenlose Macht.\nBlut tropft von der Krone und färbt deine Augen rot. Lach aus vollem Herzen, o großer neuer König. Bade in diesem Blut der Begierde und erwarte deinen unvermeidlichen Verfall."
  },
  Stage_145318_Name = {
    Text = "Krone der Begierde· einer von"
  },
  Stage_145319_Desc = {
    Text = "Endlich hast du alles, was du dir je gewünscht hast: Stärke, Reichtum, Ruhm und grenzenlose Macht.\nBlut tropft von der Krone und färbt deine Augen rot. Lach aus vollem Herzen, o großer neuer König. Bade in diesem Blut der Begierde und erwarte deinen unvermeidlichen Verfall."
  },
