  },
  Stage_145339_Name = {
    Text = "Lotan: Cetarchon Prüfungs-Level"
  },
  Stage_145340_Desc = {
    Text = "Von all den Gefahren hier sind die wilden Tiere die harmlosesten."
  },
  Stage_145340_Name = {
    Text = "Käfigbestie· Sechs"
  },
  Stage_145341_Desc = {
    Text = "Der Weg, den Astralen Cetus zu erfreuen, ist einfach: genug Blut, genug Stärke, genug Verlangen...\nWenn du über unzählige Leichen hinweggetrampelt bist, herzlichen Glückwunsch. Du hast das Recht verdient, an diesem Wettkampf teilzunehmen."
  },
  Stage_145341_Name = {
    Text = "Das Opfer· fünf"
  },
  Stage_145342_Desc = {
    Text = "Von all den Gefahren hier sind die wilden Tiere die harmlosesten."
  },
  Stage_145342_Name = {
