  Stage_146928_Desc = {
    Text = "Eine in Not geratene Prinzessin wird von einem Ritter gerettet – das ist eine altbekannte Geschichte, die jeder kennt."
  },
  Stage_146928_Name = {Text = "Prinzessin"},
  Stage_146929_Desc = {
    Text = "Der Drache erwacht, und der Hass flammt erneut auf. Der Atem des Ungeheuers bricht aus dem Fels hervor, das Gift des Krieges brennt lichterloh und ist bis heute nicht erloschen.\nDie Erde dröhnt wie Donner."
  },
  Stage_146929_Name = {
    Text = "Drachennest"
  },
  Stage_146930_Desc = {
    Text = "Der Ritter betrat einen fremden Weg, durchquerte öde Felder und Hügel, begleitet nur von seinem Schatten.\nVielleicht war er längst gestorben, doch da niemand es bezeugte, geriet es in Vergessenheit.\nDie Welt ist so still und lautlos."
  },
  Stage_146930_Name = {
    Text = "Grabstätte"
  },
  Stage_146931_Desc = {
    Text = "Vierzig Tage und Nächte fiel der Regen auf die Erde – wir können nicht weitermachen, und doch werden wir weitermachen."
  },
  Stage_146931_Name = {Text = "Apfelinsel"},
  Stage_146932_Desc = {
    Text = "Der Drache erwacht, und der Hass flammt erneut auf. Der Atem des Ungeheuers bricht aus dem Fels hervor, das Gift des Krieges brennt lichterloh und ist bis heute nicht erloschen.\nDie Erde dröhnt wie Donner."
  },
  Stage_146932_Name = {
    Text = "Drachennest"
  },
  Stage_146933_Desc = {
    Text = "Das sind die Wurzeln und Blüten des himmlischen Gartens, die Krone aller Wünsche dieser Welt, ein nie versiegender Überfluss.\nTrinke den Wein aus dem Kelch, und du wirst sehen, was du am meisten begehrt."
  },
  Stage_146933_Name = {
    Text = "Heiliger Kelch"
  },
  Stage_146934_Desc = {
    Text = "Der Drache erwacht, und der Hass flammt erneut auf. Der Atem des Ungeheuers bricht aus dem Fels hervor, das Gift des Krieges brennt lichterloh und ist bis heute nicht erloschen.\nDie Erde dröhnt wie Donner."
  },
  Stage_146934_Name = {
    Text = "Drachennest"
  },
