  Stage_20706_Name = {Text = "Von weitem"},
  Stage_20707_Desc = {
    Text = "Gott sagte, dass sie geboren wurden, um zu leiden und Blut zu vergießen.\nSo wie die Sonne aufgehen und der Regen fallen muss.\nAlles geschieht zum Besten."
