  Stage_24183_Name = {
    Text = "Rotes Dame-Testniveau"
  },
  Stage_24184_Name = {
    Text = "Demo-Level der Schlammblume"
  },
  Stage_24423_Desc = {
    Text = "Kein Bürger Londiniums würde einen frisch gebrühten heißen Tee ablehnen.\nSelbst wenn es eine Tasse Lamprey-Oolong-Tee ist."
  },
  Stage_24423_Name = {
    Text = "Neunauge–Elixier"
  },
  Stage_24424_Desc = {
    Text = "Jeder, der vom Schicksal ausgewählt wurde, glaubt, dass er die Ausnahme ist.\nDas Schicksal verspottet die Wahrscheinlichkeit."
  },
  Stage_24424_Name = {
    Text = "Gefangene des Schicksals"
  },
  Stage_24425_Desc = {
    Text = "Schnipp. \nSie schwor, alle Verbindungen zu ihrem früheren Leben abzubrechen.\nSo wie man ein Band mit einer Schere in zwei schneidet."
  },
  Stage_24425_Name = {Text = "Für Sorel"},
  Stage_24426_Desc = {
    Text = "Einmal mehr wirst du ein Gefangener des Mitgefühls, das tief in ihre Seele eintaucht."
  },
  Stage_24426_Name = {
    Text = "Gefallenes Urteil"
  },
  Stage_24427_Desc = {
    Text = "Am Anfang der Geschichte wirst du einen majestätischen Tod erleben.\nObwohl es der Anfang ist, ist es bei weitem nicht das Ende."
  },
  Stage_24427_Name = {Text = "Trinklied"},
  Stage_24428_Desc = {
    Text = "Der Name des Mädchens ist Sorel, der Stolz des Dorfes.\nGehorsam und rein, hat sie ein schneeweißes Aussehen und geht mit kleinen Schritten, wie eine wahre Dame.\nAber im Gegensatz zu jenen Damen träumt sie niemals."
  },
  Stage_24429_Desc = {
    Text = "Logik ist wie Whisky: zu viel davon verliert seinen Nutzen."
  },
  Stage_24429_Name = {
    Text = "Maskierte Harmonie"
  },
  Stage_24430_Desc = {
    Text = "Unter Seiner sorgfältigen Pflege breitete sich der Krebs der Ambition schließlich wie blühende Rosen aus."
  },
  Stage_24430_Name = {
    Text = "Blutrotes Gelage"
  },
  Stage_24431_Desc = {
    Text = "Schlürfen. Schlürfen.\nWir winden uns im Schatten, wir flüstern Geheimnisse.\nFette Körper hinterlassen gewundene Tränenflecken im Mondlicht—salzig, weißt du."
  },
  Stage_24431_Name = {Text = "Ei"},
  Stage_24432_Desc = {
    Text = "Scones, Macarons und dampfend heiße Schokolade...\nDer Wunsch der Dienerin ist einfach: besser zu essen, und noch mehr."
  },
  Stage_24432_Name = {
    Text = "Wunsch der Kammerjungfer"
  },
  Stage_24433_Desc = {
    Text = [[
Achte darauf, sei vorsichtig. 
Die Dame, die ihr alle bewundert, ist keine wahre Dame. 
Aber wen interessiert es?]]
  },
  Stage_24433_Name = {
    Text = "Damenführer"
  },
  Stage_24434_Desc = {
    Text = "Die Rose neigt ihren schlanken Kopf zu den Glocken, während der Geier sich inmitten der stinkenden Blumen verliert.\nNiemand singt, niemand spricht. Die Welt verblasst mit ihrem Verschwinden."
  },
  Stage_24434_Name = {
    Text = "Rosenbeerdigung"
  },
  Stage_24435_Desc = {
    Text = "Sie drainiert die Quellen und tötet unschuldige Vögel.\nSie bringt goldene Winde, die wie Meteoriten über die Felder fegen.\nSie setzt die Welt in Flammen mit Verlangen und verwandelt sie dann in Asche."
  },
  Stage_24435_Name = {
    Text = "Kameliendame"
  },
  Stage_24439_Desc = {
    Text = [[
Achte darauf, sei vorsichtig. 
Die Dame, die ihr alle bewundert, ist keine wahre Dame. 
Aber wen interessiert es?]]
  },
