  Stage_35099_Desc = {
    Text = "\"Schhh... rate mal, was ich durch deine Augen gesehen habe?\"\nNachdem Aurita vom Hüter zu Tränen erschreckt wurde, wollte Lotan fast die vierte Wand des Zimmers des Hüters niederreißen, weil Auritas Weinen einfach zu beunruhigend war."
  },
  Stage_35099_Name = {
    Text = "IX·Vierte Wand des Theaters"
  },
  Stage_35100_Desc = {
    Text = "\"Lass das Publikum sich nicht vollständig in die Handlung vertiefen; lass sie analysieren und kritisieren, was auf der Bühne passiert.\"\nIn Bezug auf diese Theorie kommentierte Aurita: Aurita möchte von niemandem gescholten werden! Aurita möchte einfach gute Freunde mit jedem sein!"
  },
  Stage_35100_Name = {
    Text = "VIII·Verfremdungseffekt"
  },
  Stage_35129_Desc = {
    Text = "Sie ist die Grenze, an der Träume und Realität miteinander verwoben sind, das Spiegelbild tief in jeder Seele, die den Nachthimmel betrachtet."
  },
  Stage_35129_Name = {
    Text = "Verzerrte Sterne"
  },
  Stage_35129_StageInitStateText = {
    Text = "Meeresalbtraum"
  },
  Stage_35130_Desc = {
    Text = "Sie ist bereit."
  },
  Stage_35130_Name = {
    Text = "Internalisierte Flamme"
  },
  Stage_35571_Desc = {
    Text = "Weil du Auritas Freund bist, möchte sie dich all ihren Freunden vorstellen."
  },
  Stage_35571_Name = {
    Text = "Freund-Kompendium"
  },
  Stage_35572_Desc = {
    Text = "Weil du Auritas Freund bist, möchte sie dich all ihren Freunden vorstellen."
  },
  Stage_35572_Name = {
    Text = "Freund-Kompendium"
  },
  Stage_35573_Desc = {
    Text = "Weil du Auritas Freund bist, möchte sie dich all ihren Freunden vorstellen."
  },
  Stage_35573_Name = {
    Text = "Freund-Kompendium"
  },
  Stage_35574_Desc = {
    Text = "Aurita mag dich und möchte, dass du ein Freund wirst, der sie an einem gewöhnlichen Tag begleiten kann."
  },
  Stage_35574_Name = {
    Text = "Stiller Tag"
  },
  Stage_35575_Desc = {
    Text = "Mit allen an Auritas Seite hat Aurita überhaupt keine Angst, einzuschlafen."
  },
  Stage_35575_Name = {
    Text = "Wasserpalast"
  },
  Stage_35843_Name = {
    Text = "Aequor Lady-Teststufe"
  },
  Stage_35857_Desc = {
    Text = "Die Sterne sind dorthin gegangen, wo sie hingehören, kommunizieren auf Arten, die das menschliche Verständnis übersteigen, und weben ein unsichtbares Netz, das den Fluss der Zeit und das Licht vergangener Jahre einfängt."
  },
  Stage_35857_Name = {
    Text = "Unbekannter astraler Pfad"
  },
