  Stage_36620_Desc = {
    Text = "Die Königin sitzt hoch auf ihrem Thron.\nBegleitet von endlosem Reichtum, Schätzen und einem Hauch von versunkenen kosmischen Ruinen."
  },
  Stage_36620_Name = {
    Text = "Verstoßene Königin"
  },
  Stage_36621_Desc = {
    Text = "Vor den Katastrophen war die Hauptstadt eine Erweiterung ihrer Ambitionen und Wünsche.\nNach den Katastrophen wurde die Hauptstadt zu einem Gefängnis der Nacht und Einsamkeit."
  },
  Stage_36621_Name = {Text = "Piper"},
  Stage_36887_Name = {
    Text = "Trial-Stufe: Königin der Dornen"
  },
  Stage_38756_Desc = {
    Text = "Sie schließt ihre Augen und schwebt ziellos im Nichts des Universums.\nEin Jahr, hundert Jahre... Schließlich sagt sie sich eines Tages: \"Es ist in Ordnung. Lass mich Wahrheit und Falschheit definieren.\"\nDie Königin und ihre unsterbliche Stadt – Isalaw, bleiben somit inmitten der weiten Galaxie des Universums schwebend.\nSie teilt mir die Geschichte von Isalaw mit, damit sie ewig erinnert werden kann."
  },
  Stage_38756_Name = {
    Text = "Ein Fragment der Erinnerung: Reminiszenz VI"
  },
