  Stage_38762_Name = {
    Text = "Eine Erinnerung · Rückblick I"
  },
  Stage_38763_Desc = {
    Text = "Isarau verschwand, als hätte es nie existiert.\nAlle Straßen und Menschen waren Illusionen. Sie wurden aus ihren Träumen geboren, nahmen Tag für Tag Gestalt an, und dann:\n\"Bang—\"\nDer Traum endete. Sie öffnete nie die Augen, um Isarau zu sehen, genau wie sie nie die Augen öffnete, um sich selbst zu sehen."
  },
