  Stage_38769_Name = {
    Text = "Mirage · Erinnerungen IV"
  },
  Stage_38770_Desc = {
    Text = "In der Nacht stand die Königin auf der Terrasse des Palastes und schaute auf die Stadt, die Tausende von Fuß darunter lag.\nTag für Tag, immer wenn sie versuchte, den Palast zu verlassen, folgten Schwindel, Tränen und große Gedächtnislücken.\n\"Bist du bereit? Um der Wahrheit dieser Welt zu begegnen.\"\nSie holte tief Luft und sprang von der Terrasse."
  },
  Stage_38770_Name = {
    Text = "Wahr · Reminiszenz I"
  },
  Stage_38771_Desc = {
    Text = "In der Nacht stand die Königin auf der Terrasse des Palastes und schaute auf die Stadt, die Tausende von Fuß darunter lag.\nTag für Tag, immer wenn sie versuchte, den Palast zu verlassen, folgten Schwindel, Tränen und große Gedächtnislücken.\n\"Bist du bereit? Um der Wahrheit dieser Welt zu begegnen.\"\nSie holte tief Luft und sprang von der Terrasse."
  },
  Stage_38771_Name = {
    Text = "Stimmt·Erinnerungen III"
  },
  Stage_38772_Desc = {
    Text = "Als sie ihre Augen öffnete, stand die Welt am Rande der Zerstörung.\nAlle Gebäude waren eingestürzt, schwarzer Schleim leckte am Himmel, und weiße Freesien verschwanden im ewigen Nichts.\nAlles war still. Alles schien zu schlafen.\nNur ihre Tränen waren kalt, kühlten ihr Gesicht und durchtränkten ihr Haar."
  },
  Stage_38772_Name = {
    Text = "Nun·Erinnerung IV"
  },
  Stage_38773_Desc = {
    Text = "In der Nacht stand die Königin auf der Terrasse des Palastes und schaute auf die Stadt, die Tausende von Fuß darunter lag.\nTag für Tag, immer wenn sie versuchte, den Palast zu verlassen, folgten Schwindel, Tränen und große Gedächtnislücken.\n\"Bist du bereit? Um der Wahrheit dieser Welt zu begegnen.\"\nSie holte tief Luft und sprang von der Terrasse."
  },
