  Stage_44551_Desc = {
    Text = "Barmherziger Vater, bitte vergib mir. Erlaube mir, Wiedergutmachung zu leisten und meine Sünden zu sühnen."
  },
  Stage_44551_Name = {
    Text = "Unser Fehler"
  },
  Stage_44552_Desc = {
    Text = "Der Staub hat sich gelegt. Die Schuldigen werden gerichtet, und die, die weitermachen, werden vorwärts gehen.\nMorgen wird ein neuer Tag sein."
  },
  Stage_44552_Name = {
    Text = "Entzünde die Weiße Hoffnung."
  },
  Stage_44553_Desc = {
    Text = "Es sollte ein gewöhnlicher Nachmittag sein, aber für den Hüter von Mythag ist Normalität eindeutig ein Luxus."
  },
  Stage_44553_Name = {Text = "Buße"},
  Stage_44554_Desc = {
    Text = "Reinigung, Reinigung... Ist das das Murmeln eines Wahnsinnigen oder ein verzerrter Glaube?"
  },
  Stage_44554_Name = {Text = "Blut Sigil"},
  Stage_44555_Desc = {
    Text = "Sie sind von Flammen verschlungen worden und haben ihren Verstand verloren."
  },
  Stage_44555_Name = {
    Text = "Wahnsinn der Wut"
  },
  Stage_44556_Desc = {
    Text = "Was andere haben, müssen sie auch besitzen; was andere fehlen, müssen sie umso mehr besitzen — ganz gleich wie bedeutungslos, ganz gleich wie absurd."
  },
  Stage_44556_Name = {
    Text = "Klinge der Eifersucht"
  },
  Stage_44557_Desc = {
    Text = "Halt, entspann dich, du hast genug gearbeitet; leg dich hin, schlafe ruhig, niemand wird dir die Schuld geben."
  },
  Stage_44557_Name = {
    Text = "Sich der Lethargie hingeben"
  },
  Stage_44558_Desc = {
    Text = "Du stapfst zurück den Weg, den du gekommen bist, nur um auf gefräßige Fangzähne zu treffen."
  },
  Stage_44558_Name = {
    Text = "Hunger gestillt"
  },
  Stage_44559_Desc = {
    Text = "Wenn Sie in den Spiegel schauen, sehen Sie ein Phantom oder Ihr wahres Verlangen?"
  },
  Stage_44559_Name = {
    Text = "Reinige die Sünden"
  },
  Stage_44560_Desc = {
    Text = "Barmherziger Vater, bitte vergib mir. Erlaube mir, Wiedergutmachung zu leisten und meine Sünden zu sühnen."
  },
  Stage_44560_Name = {
    Text = "Unser Fehler"
  },
