  Stage_45411_Desc = {
    Text = "Abschiedskuss"
  },
  Stage_45411_Name = {
    Text = "Abschiedskuss"
  },
  Stage_46169_Desc = {
    Text = [[
Sie hat alle Wahrscheinlichkeiten auswendig gelernt, doch wie die Theologiestudenten war sie verwirrt.
Denn Wahnsinn ist unberechenbar, und leider ist es die Norm der Welt.]]
  },
  Stage_46169_Name = {
    Text = "Grand–Slam–Pakt"
  },
  Stage_46170_Desc = {
    Text = [[
Sie hat alle Wahrscheinlichkeiten auswendig gelernt, doch wie die Theologiestudenten war sie verwirrt.
Denn Wahnsinn ist unberechenbar, und leider ist es die Norm der Welt.]]
  },
  Stage_46170_Name = {
    Text = "Grand–Slam–Pakt"
  },
  Stage_46171_Desc = {
    Text = [[
Der Fluch verwandelt dich in eine Schlange, die in ewiger Winterruhe gefangen ist.
Er ist so uralt wie deine Nabelschnur.]]
  },
  Stage_46171_Name = {
    Text = "Bitterer Fluch"
  },
  Stage_46172_Desc = {
    Text = "Das Mädchen war einst Mason.\nBald wird sie wie Ulysses—nur ein Niemand—sein.\nDoch bald wird sie für alle stehen."
  },
  Stage_46172_Name = {
    Text = "„Ursprung\""
  },
  Stage_46173_Desc = {
    Text = [[
Der Fluch verwandelt dich in eine Schlange, die in ewiger Winterruhe gefangen ist.
Er ist so uralt wie deine Nabelschnur.]]
  },
  Stage_46173_Name = {
    Text = "Bitterer Fluch"
  },
  Stage_46174_Desc = {
    Text = [[
Es endet hier, mit mir.
Teste deinen Herrn nicht.]]
  },
  Stage_46174_Name = {Text = "Endet hier"},
  Stage_46175_Desc = {
    Text = "Im Laufe der Jahre haben Pilger einen Pfad in die Schneeberge gehauen, um die Realität zu verankern.\nSie bleiben still, mit weit geöffneten Mündern, als ob sie endlos brüllen—"
  },
  Stage_46175_Name = {
    Text = "Gesang der Pilgerin"
  },
  Stage_46176_Desc = {
    Text = [[
Der Fluch verwandelt dich in eine Schlange, die in ewiger Winterruhe gefangen ist.
Er ist so uralt wie deine Nabelschnur.]]
  },
  Stage_46176_Name = {
    Text = "Bitterer Fluch"
  },
  Stage_46177_Desc = {
    Text = [[
Sie hat alle Wahrscheinlichkeiten auswendig gelernt, doch wie die Seminarstudenten war sie verwirrt.
Denn Wahnsinn ist unberechenbar. Leider ist es die Norm dieser Welt.]]
  },
  Stage_46177_Name = {
    Text = "Grand–Slam–Pakt"
  },
  Stage_46178_Desc = {
    Text = [[
Sie witnessierte sich selbst am Rande der Welteroberung.
Sie starrte schweigend auf den langen, schmalen Schatten.]]
  },
  Stage_46178_Name = {
    Text = "Schattenmärchen"
  },
  Stage_46179_Desc = {
    Text = "Ihre Komödie ist einzigartig. Sie besteht aus endlosen einsamen Nächten, dem Mond und Tränen."
  },
  Stage_46179_Name = {
    Text = "Warten auf die Komödie"
  },
  Stage_46180_Desc = {
    Text = "Wenn alle Dinge schlafen, erwacht die Schlange.\nWenn alles zerfällt, wird die Schlange ihre Form wiederherstellen."
  },
  Stage_46180_Name = {
    Text = "Schlaflose Schlange"
  },
  Stage_46181_Desc = {
    Text = "Die Katze teilt ihre Emotionen in achtzehn Stücke und erfindet verschiedene Tonhöhen von \"schnurr\"-Lauten für sie.\nSo kann sie sagen: „Ich habe Hunger“, „Spiel mit mir“, „Stör mich nicht“.\nSie kann auch sagen: „Ich vermisse dich“."
  },
  Stage_46181_Name = {
    Text = "Allwissende Katze"
  },
  Stage_46182_Desc = {
    Text = "Mit dem Läuten der alten Glocke kommt ein schwaches und verblassendes Segenswort.\nFrohe Feiertage. Frohe Feiertage. Frohe Feiertage."
  },
  Stage_46182_Name = {
    Text = "Goldene Fuge"
  },
