  Stage_46546_Name = {
    Text = "Unbewusste Erinnerung: Auftauchen II"
  },
  Stage_46547_Desc = {
    Text = "Ich weiß nicht, wann sie hier die Richterin wurde.\nSie verurteilte eine Person, deren Name verborgen war, und verurteilte sie zum Tod.\nDann hörte sie die Offenbarung: \"Du bist diese Person.\"\nJa, alle Gefangenen, Richter und Priester hier haben das gleiche Gesicht"
  },
  Stage_46547_Name = {
    Text = "Amygdala·Auftauchung IV"
  },
  Stage_46548_Desc = {
    Text = "Hölle ist ein leerer Raum, gefüllt mit unzähligen Spiegeln.\nSie wagt es nicht, ihre Augen zu öffnen, denn alles, was sie sieht, ist ihr blasses, verängstigtes Gesicht.\nEine Stimme hallt im Nichts:\nDas ist Vergeltung. Im Leben hattest du nur eine einzige Hülle; im Tod siehst du dich unzähligen gegenüber."
  },
  Stage_46548_Name = {
    Text = "Spiegel·Entstehung VI"
  },
  Stage_46549_Desc = {
    Text = "Ich weiß nicht, wann sie hier die Richterin wurde.\nSie verurteilte eine Person, deren Name verborgen war, und verurteilte sie zum Tod.\nDann hörte sie die Offenbarung: \"Du bist diese Person.\"\nJa, alle Gefangenen, Richter und Priester hier haben das gleiche Gesicht"
  },
  Stage_46549_Name = {
    Text = "Amygdala·Auftauchung II"
  },
  Stage_46550_Desc = {
    Text = "Ich weiß nicht, wann sie hier die Richterin wurde.\nSie verurteilte eine Person, deren Name verborgen war, und verurteilte sie zum Tod.\nDann hörte sie die Offenbarung: \"Du bist diese Person.\"\nJa, alle Gefangenen, Richter und Priester hier haben das gleiche Gesicht"
  },
  Stage_46550_Name = {
    Text = "Amygdala · Auftauchung III"
  },
  Stage_46551_Desc = {
    Text = "Im 315. Jahr der Hongji-Ära, am 2. Dezember, wurde sie als immateriell erklärt.\nSie rief laut, aber niemand antwortete; sie stahl Brot, wurde jedoch nicht gefangen genommen oder eingesperrt.\nEine Krankheit namens Vergessenheit infizierte alle, wobei sie die einzige Ausnahme blieb."
  },
  Stage_46551_Name = {
    Text = "Erscheinen Sieben der Vergessenskurve"
  },
