  Stage_53791_Name = {
    Text = "Puppenspiel·Episode 4"
  },
  Stage_53792_Desc = {
    Text = "Sie wird den Anweisungen des Skripts folgen und einen Akt nach dem anderen durchführen, endlosen Chaos heraufbeschwörend. \nUnd sie ist die Tänzerin, die anmutig im Auge des Orkans schwebt. \nSie war schon immer die engagierteste Schauspielerin."
  },
