  Stage_53797_Name = {
    Text = "Unvollendetes Skript · Teil 3"
  },
  Stage_53798_Desc = {
    Text = "Ihr langbeiniges Onkel war anders: Er war aus Nebel gemacht.\nDa das Mädchen den Glauben an die Menschen verloren hatte, bedeutete es ihr nichts, ob es Nebel, Gold oder Symbole waren.\nNatürlich würde sie letztendlich für dieses Missverständnis zahlen—aber das ist eine Geschichte für eine andere Zeit."
  },
  Stage_53798_Name = {
    Text = "Onkel Langbeine·VI"
