  Stage_55142_StageInitStateText = {Text = "Ende"},
  Stage_55143_Desc = {
    Text = "Das kleine Blumenhaus ist ihr kleines Königreich.\nIn diesem kleinen Königreich haben sie nichts, doch sie sind zufrieden."
  },
  Stage_55143_Name = {
    Text = "Königreich · IV"
  },
  Stage_55144_Desc = {
    Text = "Das beliebte Gedicht brachte alles, und sie wurde bei dem Lob ihrer Freundin rot. Ihr Gedicht hatte schließlich ihre Freundin vom Leiden befreit. So dachte sie.\nDoch was sie nicht hörte, war, dass die Samen des Unheils bereits gesät worden waren und darauf warteten, sich fest zu umschlingen und die Rosen zu zerstören."
  },
  Stage_55144_Name = {
    Text = "Blühende Gedichte: Kapitel 5"
  },
  Stage_55145_Desc = {
