  Stage_55167_Name = {
    Text = "Die Erste Rose·Teil 1"
  },
  Stage_55391_Desc = {
    Text = "\"Lass mich die erste Rose gegen dein erstes Gedicht eintauschen.\""
  },
  Stage_55391_Name = {Text = "Psalm 1843"},
  Stage_55392_Desc = {
    Text = "Der Garten ist ein Rätsel, und die Rose ist ihre Antwort."
  },
  Stage_55392_Name = {
    Text = "Verbleibender Duft"
  },
  Stage_55393_Desc = {
    Text = "\"Lass mich die erste Rose gegen dein erstes Gedicht eintauschen.\""
  },
  Stage_55393_Name = {Text = "Psalm 1843"},
  Stage_55394_Desc = {
    Text = "Kein Trauern, kein Wind.\nNur die nachhallende Tinte des Dichters schlägt die Sterbeglocke für den Garten."
  },
  Stage_55394_Name = {
    Text = "Gartenklage"
  },
  Stage_55395_Desc = {
    Text = "Die Statue ist die Rhetorik des Königs; Stille ist die Rhetorik der Statue."
  },
  Stage_55395_Name = {
    Text = "Statuarische Rhetorik"
  },
  Stage_55396_Desc = {
    Text = "Sie schauen sich über den Garten an.\nDer Garten enthält unzählige Pfade für jeden von ihnen, die alle in verschiedene Richtungen führen."
  },
  Stage_55396_Name = {
    Text = "Garten der gabelten Wege"
  },
  Stage_55397_Desc = {
    Text = "Lebewohl zu den Knochen bei der ersten Beerdigung, und zu der Zeit bei der zweiten."
  },
  Stage_55397_Name = {
    Text = "Vergängliche Beerdigung"
  },
  Stage_55398_Desc = {
    Text = "\nAusgezeichnete Poesie taucht den Leser ein.\nDie klassische Ästhetiktheorie führt es so ein."
  },
  Stage_55398_Name = {
    Text = "Dichterfigur"
  },
  Stage_55399_Desc = {
    Text = "Die blühenden Blumen von Cité haben dir eine Einladung ausgesprochen, dich gemeinsam mit ihnen in diesen Traum zu begeben."
  },
  Stage_55399_Name = {
    Text = "Stadt der Blüten"
  },
  Stage_55400_Desc = {
    Text = "Das sogenannte Heimatdorf ist nichts weiter als eine langanhaltende Lüge."
  },
  Stage_55400_Name = {Text = "Zuhause"},
  Stage_55401_Desc = {
    Text = "\"Lass mich die erste Rose gegen dein erstes Gedicht eintauschen.\""
  },
  Stage_55401_Name = {Text = "Psalm 1843"},
  Stage_55551_Desc = {
    Text = "Dieser Schneeberg hat Leben, mit Echos, die durch den Berg hallen und nach seiner Tochter rufen.\nKomm schnell, komm.\nIst es die Tochter, die zur Mutter geht, oder die Mutter, die zur Tochter geht?\nAm Gipfel des Berges treffen sich schließlich zwei leere Mägen."
  },
  Stage_55551_Name = {
    Text = "Die Berge sehen: Teil III"
  },
  Stage_55552_Desc = {
    Text = "Dieser Schneeberg hat Leben, mit Echos, die durch den Berg hallen und nach seiner Tochter rufen.\nKomm schnell, komm.\nIst es die Tochter, die zur Mutter geht, oder die Mutter, die zur Tochter geht?\nAm Gipfel des Berges treffen sich schließlich zwei leere Mägen."
  },
  Stage_55552_Name = {
    Text = "Die Berge sehen: Teil II"
  },
  Stage_55553_Desc = {
    Text = "Dieser Schneeberg hat Leben, mit Echos, die durch den Berg hallen und nach seiner Tochter rufen.\nKomm schnell, komm.\nIst es die Tochter, die zur Mutter geht, oder die Mutter, die zur Tochter geht?\nAm Gipfel des Berges treffen sich schließlich zwei leere Mägen."
  },
  Stage_55553_Name = {
    Text = "Die Berge sehen: Teil I"
  },
  Stage_55554_Desc = {
    Text = "Der Permafrost des Schneeberges trocknet und verblasst, erlischt allen Lebens.\nDoch der Wille des Lebens bleibt stark.\nSobald der Schnee schmilzt, fallen kalte Tropfen auf den Boden.\nEin unbesiegbarer Samen wird am Gipfel sprießen."
  },
