  Stage_56893_Name = {
    Text = "Puppenhaus · Teil 6"
  },
  Stage_56894_Desc = {
    Text = "Es gab ursprünglich keine Türen in dieser Welt. \nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Arten von Türen entstanden. \nJeder sagt, hinter seiner Tür liege das Paradies. \nDoch ach, die alte Prophezeiung hat bereits längst gesagt: Es gab nie eine Tür in dieser Welt. \nWer versucht, das Paradies auf Erden zu errichten, wird am Ende das Tor zur Hölle öffnen."
  },
  Stage_56894_Name = {
    Text = "Prophezeiung des Chaos · Teil 6"
  },
  Stage_56895_Desc = {
    Text = "Die Puppe hält Fäden in der Hand, die mit den Teilen der Welt verbunden sind. \n Klick, Zisch – bewege die Finger, und die Welt bricht zusammen. \n Was hängt erneut über dem Kopf der Puppe und zwingt sie, weiterhin für die Leere zu tanzen?"
  },
  Stage_56895_Name = {
    Text = "Puppenspiel-Linie·Zwei"
  },
  Stage_56896_Desc = {
    Text = "Es gab ursprünglich keine Türen in dieser Welt.\nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Arten von Türen entstanden.\nJeder sagt, hinter seiner Tür befindet sich das Paradies.\nDoch ach, die alte Prophezeiung hat bereits klar ausgesprochen, dass es in dieser Welt von Anfang an keine Türen gab.\nWer versucht, im irdischen Leben ein Paradies zu errichten, wird am Ende die Pforten der Hölle öffnen."
  },
  Stage_56896_Name = {
    Text = "Prophezeiung des Chaos · Teil 4"
  },
  Stage_56897_Desc = {
    Text = "Es gab ursprünglich keine Türen auf der Welt. \nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Arten von Türen entstanden. \nJeder behauptet, hinter seiner Tür läge das Paradies. \nDoch ach, die alte Prophezeiung hat bereits längst gesagt, dass es auf der Welt niemals eine Tür gegeben hat. \nWer versucht, im Diesseits das Paradies zu errichten, der wird am Ende das Tor zur Hölle öffnen."
  },
  Stage_56897_Name = {
    Text = "Prophezeiung des Chaos · Teil 5"
  },
  Stage_56898_Desc = {
    Text = "In dieser Welt gab es ursprünglich keine Türen. \nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Arten von Türen entstanden. \nJeder sagt, hinter seiner Tür liege das Paradies. \nDoch ach, die alte Prophezeiung hat bereits längst gesagt, dass es in dieser Welt von Anfang an keine Türen gab. \nWer versucht, im Diesseits ein Paradies zu errichten, wird am Ende das Tor zur Hölle öffnen."
  },
  Stage_56898_Name = {
    Text = "Prophezeiung des Chaos · Teil II"
  },
  Stage_56899_Desc = {
    Text = "Es gab ursprünglich keine Türen auf der Welt. \nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Arten von Türen gab es auf der Welt. \nJeder sagt, hinter seiner Tür läge das Paradies. \nDoch ach, das alte Prophezeiung hat bereits gesagt, dass es auf der Welt von Anfang an keine Tür gab. \nWer versucht, das Paradies auf Erden zu errichten, der wird am Ende das Tor zur Hölle öffnen."
  },
  Stage_56899_Name = {
    Text = "Prophezeiung des Chaos·Dritte"
  },
  Stage_56900_Desc = {
    Text = "Fäden hängen aus der Hand der Puppe und verbinden die Teile der Welt. \n Klick, Zischen – mit einem Fingerschnippen bricht die Welt zusammen. \n Was hängt erneut über dem Kopf der Puppe und zwingt sie, weiterhin für die Leere zu tanzen?"
  },
  Stage_56900_Name = {
    Text = "Puppenspiel-Linie·Fünf"
  },
  Stage_56901_Desc = {
    Text = "Es gab ursprünglich keine Türen in dieser Welt.\nJe mehr Menschen eine Tür wollten, desto mehr verschiedene Türen gab es auf der Welt.\nJeder sagt, hinter seiner Tür liegt das Paradies.\nDoch ach, die alte Prophezeiung hat bereits längst verkündet, dass es auf der Welt niemals eine Tür gegeben hat.\nWer versucht, im Diesseits ein Paradies zu errichten, wird am Ende das Tor zur Hölle öffnen."
  },
  Stage_56901_Name = {
    Text = "Prophezeiung des Chaos · Teil 1"
  },
  Stage_56902_Desc = {
    Text = "Tanze, tanze, halte deine Schritte nicht an. \nHebe deinen Rocksaum, drehe dich im Kreis, denn die Welt dreht sich bereits unaufhörlich im Strudel. \nLass alle Sorgen hinter dir und beteilige dich an der letzten Ekstase. \nSolange du mit ganzer Kraft tanzt, wirst du die ewige untergehende Sonne sehen."
  },
  Stage_56902_Name = {
    Text = "Tanzfest · Teil 1"
  },
  Stage_56903_Desc = {
    Text = "Tanze, tanze, halte deine Schritte nicht an. \nHebe den Saum deines Kleides, drehe dich im Kreis, denn die Welt dreht sich bereits unaufhörlich im Strudel. \nLass alle Sorgen hinter dir und beteilige dich an der letzten großen Feier. \nSolange du mit ganzer Kraft tanzst, wirst du die ewige untergehende Sonne sehen können."
  },
  Stage_56903_Name = {
    Text = "Tanzfest · Teil 2"
  },
  Stage_56904_Desc = {
    Text = "Tanze, tanze, halte deine Schritte nicht auf. \n Hebe den Saum deines Kleides, drehe dich im Kreis – die Welt dreht sich bereits unaufhörlich im Strudel. \n Gib alle Sorgen auf und beteilige dich an der letzten Feier. \n Solange du mit ganzer Kraft tanzst, wirst du die ewige untergehende Sonne sehen."
  },
  Stage_56904_Name = {
    Text = "Tanzfest – Teil 3"
  },
  Stage_56905_Desc = {
    Text = "Tanz, tanz, halte deine Schritte nicht an. \n Hebe den Saum, drehe dich im Kreis, denn die Welt dreht sich bereits unaufhörlich im Strudel. \n Lass alle Sorgen hinter dir und nimm teil an der letzten Ekstase. \n Solange du leidenschaftlich tanzt, wirst du die ewige untergehende Sonne sehen."
  },
  Stage_56905_Name = {
    Text = "Tanzfest - Teil 4"
  },
  Stage_56906_Desc = {
    Text = "Tanze, tanze, halte deine Schritte nicht auf. \n Hebe den Saum deines Kleides, drehe dich im Kreis, denn die Welt dreht sich bereits unaufhörlich im Strudel. \n Lass alle Sorgen hinter dir und nimm teil am letzten Fest. \n Solange du leidenschaftlich tanzt, wirst du die ewige untergehende Sonne sehen."
  },
  Stage_56906_Name = {
    Text = "Tanzfest · Teil 5"
  },
  Stage_56907_Desc = {
    Text = "Tanz, tanz, halte deine Schritte nicht auf. \n Hebe den Saum deines Kleides, drehe dich im Kreis, denn die Welt dreht sich bereits unaufhörlich im Strudel. \n Gib alle Sorgen auf und nimm teil an der letzten Feier. \n Solange du leidenschaftlich tanzt, wirst du die ewige untergehende Sonne sehen."
  },
  Stage_56907_Name = {
    Text = "Tanzfest · Teil 6"
  },
  Stage_56908_Desc = {
    Text = "Symphonie ist kein Solo.\nStreicher, Holzbläser, Blechbläser, Schlaginstrumente.\nJede regimentierte Instrumentengruppe neigt ihre Köpfe und wartet auf seine Führung"
  },
  Stage_56908_Name = {
    Text = "Orchestrierung: Teil Fünf"
  },
  Stage_56909_Desc = {
    Text = "Blühe wie ein Feuerwerk, selbst wenn dein Leben als Brennstoff dient. \nDa das Ziel doch ähnlich ist, warum nicht den langen Schmerz überspringen und stattdessen strahlendes Licht gewinnen."
  },
  Stage_56909_Name = {
    Text = "Glänzende Vernichtung · Teil 2"
  },
  Stage_56910_Desc = {
    Text = "Unzählige Menschen sehnen sich nach der Wahrheit und stürzen sich einer nach dem anderen hinein.\nUnzählige Menschen halten die Fragmente der Wahrheit in Händen, glauben, dass ihre blinden Augen nun das Licht sehen, und beginnen, die Herrlichkeit des Himmels zu predigen.\nNur sie fand den Wein der Wahrheit und trank diesen Nektar in einem Zug.\nGluck.\nSie brach betrunken zusammen, das Gift drang bis ins Mark.\nTatsächlich haben bereits unzählige Narren bewiesen, dass die Wahrheit nur ein vergifteter Becher ist.\nWer wenig trinkt, dem vergeht das Gift, wer viel trinkt, stirbt.\nJetzt hat sie nicht mehr viel Zeit, sie möchte nur noch mit dir gemeinsam kosten."
  },
  Stage_56910_Name = {
    Text = "Wahrheitsgift·Teil 5"
  },
  Stage_56911_Desc = {
    Text = "Sie streckt dir die Hand entgegen, um dich als Tanzpartner einzuladen. \nVorwärts, rückwärts – diese Harmonie gehört nur euch beiden. \nHalte sanft ihre Handfläche und folge ihren Schritten, ohne das Haupt eines Gentleman zu senken. \nSelbst wenn sich unter deinen Füßen bereits der Abgrund auftut."
  },
  Stage_56911_Name = {
    Text = "Einladung · Teil 5"
  },
  Stage_56912_Desc = {
    Text = "Sie streckt dir die Hand entgegen und lädt dich ein, ihr Tanzpartner zu werden. \nVorwärts, rückwärts – diese Harmonie ist nur euch beiden vorbehalten. \nNimm sanft ihre Hand, folge ihren Schritten, und senke nicht das Haupt eines Gentleman. \nSelbst wenn sich unter deinen Füßen bereits der Abgrund auftut."
  },
  Stage_56912_Name = {
    Text = "Einladung · Teil 4"
  },
  Stage_56913_Desc = {
    Text = "Sie streckt die Hand aus, um dich als ihren Tanzpartner einzuladen.  \nVorwärts, rückwärts – diese Harmonie ist nur euch beiden eigen.  \nHalte ihre Hand sanft und folge ihren Schritten, ohne das Haupt eines Gentleman zu senken.  \nSelbst wenn sich unter deinen Füßen bereits der Abgrund auftut."
  },
  Stage_56913_Name = {
    Text = "Einladung · Teil 6"
  },
  Stage_56914_Desc = {
    Text = "Sie streckt dir die Hand entgegen und bittet dich, ihr Tanzpartner zu werden. \nVorwärts, rückwärts – diese Harmonie ist nur euch beiden vorbehalten. \nHalte ihre Hand sanft und folge ihren Schritten, ohne das Haupt des Gentleman zu senken. \nSelbst wenn sich unter deinen Füßen bereits der Abgrund auftut."
  },
  Stage_56914_Name = {
    Text = "Einladung·Teil 1"
  },
  Stage_56915_Desc = {
    Text = "Sie streckt dir die Hand entgegen, um dich als Tanzpartner einzuladen. \nVorwärts, rückwärts – diese Harmonie ist nur euch beiden vorbehalten. \nHalte ihre Handfläche sanft und folge ihren Schritten, ohne das Haupt eines Gentleman zu senken. \nSelbst wenn sich unter euren Füßen bereits der Abgrund auftut."
  },
  Stage_56915_Name = {
    Text = "Einladung·Teil 3"
  },
  Stage_56916_Desc = {
    Text = "Sie streckt dir die Hand entgegen und lädt dich ein, ihr Tanzpartner zu werden.  \nVorwärts, rückwärts – diese stille Übereinkunft teilen nur ihr beide.  \nHalte sanft ihre Handfläche, folge ihren Schritten und senke nicht das Haupt des Gentleman.  \nSelbst wenn sich unter deinen Füßen bereits der Abgrund auftut."
  },
  Stage_56916_Name = {
    Text = "Einladung·Teil 2"
  },
  Stage_56917_Desc = {
    Text = "Blühe wie ein Feuerwerk, selbst wenn dein Leben als Brennstoff dient. \nDa das Ziel doch ähnlich ist, warum nicht den langen Schmerz weglassen und stattdessen strahlendes Licht gewinnen?"
  },
