  Stage_58385_Name = {
    Text = "Mirage·Wahnsinn"
  },
  Stage_58385_StageInitStateText = {Text = "Ende"},
  Stage_58386_Desc = {
    Text = "Sie schließt ihre Augen und schwebt ziellos im Nichts des Universums.\nEin Jahr, hundert Jahre... Schließlich sagt sie sich eines Tages: \"Es ist in Ordnung. Lass mich Wahrheit und Falschheit definieren.\"\nDie Königin und ihre unsterbliche Stadt – Isalaw, bleiben somit inmitten der weiten Galaxie des Universums schwebend.\nSie teilt mir die Geschichte von Isalaw mit, damit sie ewig erinnert werden kann."
  },
  Stage_58386_Name = {
    Text = "Eine Erinnerung·Fünf"
  },
