  },
  Stage_59502_Desc = {
    Text = "Stellen Sie sich Ihrer urtümlichen Verzweiflung. Stellen Sie sich Ihrer urtümlichen Angst.\nStehen Sie unsichtbar nebeneinander und besiegen Sie Ihn dann"
  },
  Stage_59502_Name = {
    Text = "Entscheidung: Urschatten"
  },
  Stage_59503_Desc = {
    Text = "Erinnere dich an dein Gelübde, vergiss dein Angebot."
  },
  Stage_59503_Name = {Text = "Ritus"},
  Stage_59503_StageInitStateText = {
    Text = "Ursprünglich"
  },
  Stage_59504_Desc = {
    Text = "Im Tempel des Traums stehend, die eingestürzten Ruinen stützend.\nDie Staubpartikel unter dir bewachend, das Staubkorn, das all deine Sorge und Bindung trägt."
  },
  Stage_59504_Name = {Text = "Traumbruch"},
