  Stage_59511_Name = {Text = "Ritus"},
  Stage_62348_Desc = {
    Text = "Das ist der Höhepunkt der Sterne. Das ist das Ende des Universums.\nIn dieser Stille, höre genau—\nKannst du die wahren Töne hören?"
  },
  Stage_62348_Name = {Text = "Finale"},
  Stage_66016_Desc = {
    Text = "Er ist der höchste Wille, das Relikt des Universums, der Ende aller Dinge.\nWeine vor ihm. Für deinen zerbrechlichen Mut, für seine grenzenlose Autorität."
  },
  Stage_66016_Name = {
    Text = "Armenseele·Blick der Trauer"
  },
  Stage_66016_StageInitStateText = {
    Text = "Ursprünglich"
  },
  Stage_66017_Desc = {
    Text = "Er ist der höchste Wille, das Relikt des Universums, der Ende aller Dinge.\nWeine vor ihm. Für deinen zerbrechlichen Mut, für seine grenzenlose Autorität."
  },
  Stage_66017_Name = {
