  Stage_75771_Desc = {
    Text = "Das graue Meer erstreckt sich endlos.\nAlle verlassenen Seelen versammeln sich hier, während die Wellen tosen, aufsteigen und fallen.\nSie drängen sich zusammen, lachen und weinen; sie beobachten dich und erwarten den nächsten Gefährten."
  },
  Stage_75771_Name = {
    Text = "Zurück zum Meer aus Asche · Teil 3"
  },
