  Stage_75777_Name = {
    Text = "Zurück zum Meer aus Asche · Teil 4"
  },
  Stage_7635_Desc = {
    Text = "Sie sind wie flüchtige Zauberer, die in den Rissen von Zeit und Raum umhertreiben. \nKein Hass, keine Angst, keine Gnade."
  },
  Stage_7635_Name = {
    Text = "Kosmische Überreste II"
  },
  Stage_7636_Desc = {
    Text = "Sie trägt das heilige Relikt, führt die Gläubigen mit Lehre und verbreitet den Glauben mit giftigen Fangzähnen."
  },
  Stage_7636_Name = {
    Text = "Frommer Griff III"
  },
  Stage_7637_Desc = {
    Text = [[
Sie existierten lange bevor die Sterne entstanden sind. 
Sie sind sowohl Nichts als auch Alles.]]
  },
  Stage_7637_Name = {
    Text = "Chaotische Überreste V"
  },
  Stage_7638_Desc = {
    Text = "Sie bewachen still die Geheimnisse des Ozeans, mit Seelen so tief wie das Universum."
  },
  Stage_7638_Name = {
    Text = "Abgründige Überreste V"
  },
  Stage_76399_Desc = {
    Text = "Die Dunkelheit strömt aus dem Abgrund, während Eindringlinge inmitten der Angst, die ihre Herzen ergreift, kämpfen, bevor sie von der Dunkelheit verschlungen werden."
  },
  Stage_76399_Name = {
    Text = "Regionaler d-effect Sperrzone · Welle 4 · Level V Alarm"
  },
  Stage_7639_Desc = {
    Text = "Sie verdrehen und verschmelzen sich in der Dunkelheit, dann werden sie sorgfältig in den Idolen aufbewahrt.\nDies ist ein lang erwartetes Wiedersehen."
  },
  Stage_7639_Name = {
    Text = "Ultra Reise·Riss I"
  },
