  Stage_77102_Name = {
    Text = "Regionaler d-effect Bereich·Welle 4·Level III Alarm"
  },
  Stage_77103_Desc = {
    Text = "In diesem Moment wurden die alten Katastrophen wiederbelebt, überquerten die Grenze dieser Welt und entzündeten den gefallenen Ozean."
  },
  Stage_77103_Name = {
    Text = "Regionaler d-effect Bereich·Welle 5·Level III Alarm"
  },
  Stage_7710_Desc = {
    Text = "Tagebücher sind Fragmente des Gedächtnisses.\nTagebücher werden immer während der Untersuchungen entdeckt."
  },
  Stage_7710_Name = {
    Text = "Erinnerungssplitter"
  },
  Stage_7711_Desc = {
    Text = "Dies ist ein Reich, das für sie erschaffen wurde, das sowohl tiefe Liebe als auch einen erschreckenden Käfig verkörpert."
  },
  Stage_7711_Name = {Text = "Asyl"},
  Stage_7712_Desc = {
    Text = "Wenn die Adligen ihre Macht verlieren und die Reichen ihr Vermögen verlieren, sind sie hilflos, so wie Sie es jetzt sind."
  },
  Stage_7712_Name = {
    Text = "Kuckucksasyl"
  },
  Stage_7713_Desc = {
    Text = "Konflikte in dieser Welt beschränken sich nicht nur auf Kämpfe auf dem Schlachtfeld; manchmal sind sie auch in den Worten der Verrückten zu finden."
  },
  Stage_7713_Name = {
    Text = "Mund des Wahnsinnigen"
  },
  Stage_7714_Desc = {
    Text = "Im Nebel verwoben, treten zahllose Schritte, jeder Schritt hinterfragt das Schicksal."
  },
  Stage_7714_Name = {
    Text = "Pfad abseits"
  },
  Stage_7715_Desc = {
    Text = "Die still flamende Flamme gibt leere Versprechungen an Reisende."
  },
  Stage_7715_Name = {
    Text = "Mottenfängerfeuer"
  },
  Stage_7716_Desc = {
    Text = "Biete die Realität, die aus Caro, einem unersättlichen Abgrund, geschmiedet wurde."
  },
  Stage_7716_Name = {
    Text = "Organische Überreste V"
  },
  Stage_7717_Desc = {
    Text = "Der Sturm braut sich immer noch zusammen; er ist noch nicht vorbei."
  },
  Stage_7717_Name = {
    Text = "Realitätsneustart"
  },
  Stage_7718_Desc = {
    Text = "Segle in Richtung Land, in Richtung eines Schimmers der Hoffnung."
  },
  Stage_7718_Name = {
    Text = "Traurige Einschiffung"
  },
  Stage_7719_Desc = {
    Text = "Das war kein Leben, das zu erwarten war, sondern lediglich ein schmutziger Parasit."
  },
  Stage_7719_Name = {Text = "Parasit"},
  Stage_7720_Desc = {
    Text = "Das verlockende Licht in der endlosen Nacht verfolgen, wie eine Motte, die zum Feuer zieht, hinauf zur Flamme des Schicksals schwebend."
  },
  Stage_7720_Name = {
    Text = "Scheiterlaus"
  },
  Stage_7721_Desc = {
    Text = "Die Nacht wird von dunklen Strömungen erodiert, und die Sterne schweigen. Ein Monat der Krise, voller Wendungen und Stürme, spiegelt ruhig eine unbekannte Zukunft wider."
  },
  Stage_7721_Name = {Text = "Krisenmond"},
  Stage_7722_Desc = {
    Text = "Beben und kämpfen im Sturm des Schicksals, aber es wird niemals wirklich davon treiben."
  },
  Stage_7722_Name = {Text = "Abgrund"},
  Stage_7723_Desc = {
    Text = "Freundschaften, die den Lauf der Zeit überstanden haben, tragen neue Hoffnung."
  },
  Stage_7723_Name = {
    Text = "Alte Bindungen, neu"
  },
  Stage_7724_Desc = {
    Text = "Sein Reich ist die Hülle des Universums, und Seine Begierden sind grenzenlos."
  },
  Stage_7724_Name = {
    Text = "Wurmhöhle III"
  },
  Stage_7725_Desc = {
    Text = "Biete die Realität, die aus Caro, einem unersättlichen Abgrund, geschmiedet wurde."
  },
  Stage_7725_Name = {
    Text = "Organische Überreste II"
  },
  Stage_7726_Desc = {
    Text = "Sie waren ursprünglich eine unbewusste Mischung aus Traurigkeit, Verzerrung und Naivität,\naber wurden als fröhliche Kinder, Erwachsene und Haustiere verkleidet.\nDa sie nie den Geschmack des Glücks erfahren haben, wurden sie zu den schlechtesten Schauspielern."
  },
  Stage_7726_Name = {
    Text = "Das Geheimnis der Wachs-Skulptur I"
  },
  Stage_7727_Desc = {
    Text = "Es lehnt mit einer sanften Haltung gegen das Bett, seine stumpfen Knopfaugen starren ins Nichts.\nDer kleine Körper trägt all die Tränen seines Besitzers, kann aber keine tröstenden Worte bieten."
  },
  Stage_7727_Name = {
    Text = "Tränen der Puppe I"
  },
  Stage_7728_Desc = {
    Text = "\"Es ist der eine, das Ganze, die Hoffnung, die die Tür zur Wahrheit öffnet.\" \nZahlreiche Schlüssel bilden einen Kreis. Sie fallen vom Himmel und bringen schwere Hoffnung.\nUnd schwere Gräber."
  },
  Stage_7728_Name = {
    Text = "Phantasmagorischer Tauchgang I"
  },
  Stage_7729_Desc = {
    Text = "\"Es ist der eine, das Ganze, die Hoffnung, die die Tür zur Wahrheit öffnet.\" \nZahlreiche Schlüssel bilden einen Kreis. Sie fallen vom Himmel und bringen schwere Hoffnung.\nUnd schwere Gräber."
  },
  Stage_7729_Name = {
    Text = "Phantasmaler Sturzflug III"
  },
  Stage_7730_Desc = {
    Text = "\"Es ist der eine, das Ganze, die Hoffnung, die die Tür zur Wahrheit öffnet.\" \nZahlreiche Schlüssel bilden einen Kreis. Sie fallen vom Himmel und bringen schwere Hoffnung.\nUnd schwere Gräber."
  },
