  Stage_7758_Desc = {
    Text = "Das \"Tor\" öffnet sich gleich und offenbart einen Blick auf die Wahrheit.\nSie ist weder schwarz noch weiß—die Wahrheit ist bunt und doch trüb."
  },
  Stage_7758_Name = {
    Text = "Sumpf von Caro: Rotierender Riss I"
  },
  Stage_7759_Desc = {
    Text = "Wenn der Regen fällt und das Blut fließt, kommt der Moment unserer Wiedervereinigung.\nLange nicht gesehen, Hüter."
  },
  Stage_7759_Name = {Text = "Zufall"},
  Stage_7760_Desc = {
    Text = "Unter der verlassenen Eisenbahnbrücke gibt ein riesiges, aufgeblähtes Ungeheuer seltsame Geräusche von sich. Um das Ra'i Asyl zu erreichen, musst du hierüber gehen."
  },
  Stage_7760_Name = {
    Text = "Der Strom wird dich leiten"
  },
