  Stage_7814_Desc = {
    Text = "Es war die kolossale Klinge eines, der die Meere spalten wollte, verkörperte den Ehrgeiz, alle Meere zu unterwerfen."
  },
  Stage_7814_Name = {
    Text = "Wahnsinniger Küchenmesser"
  },
  Stage_7815_Desc = {
    Text = "Die Realität sät die Samen des Unglücks, aber das Schicksal lenkt das Treffen."
