  },
  Stage_8124_Name = {
    Text = "Phantasmaler Sturzflug IV"
  },
  Stage_8125_Desc = {
    Text = "Die Krankheit, die hier wütet, ist keine gewöhnliche Krankheit."
  },
  Stage_8125_Name = {Text = "Maladie"},
  Stage_8126_Desc = {
    Text = "Du und Ramona machen euch auf den Weg zum östlichen Stadtteil von Londinium, zum Waisenhaus Lillian, für eure erste Untersuchung als neue Hüter.\nAlles wird reibungslos verlaufen, richtig?"
  },
  Stage_8126_Name = {
    Text = "Man soll nicht nach dem Äußeren urteilen"
  },
  Stage_8127_Desc = {
    Text = "Geister lauern im Schatten—unterirdisch oder im menschlichen Herzen."
  },
  Stage_8127_Name = {
    Text = "Unterirdische Gespenster"
  },
  Stage_8128_Desc = {
    Text = "Kein Sauerstoff zum Atmen, kein schwaches Licht; dies ist ein absolut schwarzer Traum."
  },
  Stage_8128_Name = {
    Text = "Pechschwarzer Traum"
  },
  Stage_8129_Desc = {
    Text = "„Jeder Schlüssel hat eine einzigartige Nummer, die nur einem einzelnen Ermittler entspricht.“\n„So bedeutet der Fall jedes Schlüssels den Tod eines einzigartigen Ermittlers.“\n„Wie wunderbar. Sogar der Tod ist einzigartig.“"
  },
  Stage_8129_Name = {
    Text = "Phantasmaler Sturzflug VII"
  },
