  },
  Stage_88923_Name = {
    Text = "Narren·Teil 3"
  },
  Stage_88924_Desc = {
    Text = "Die Zusammensetzung der Wüste ist: glühende Hitze, Trockenheit, Wind und Kies, endlose Sanddünen, agile Reptilien, Kakteen und eine Schönheit mit honigfarbenem Skin."
  },
  Stage_88924_Name = {
    Text = "Sand und Honig"
  },
  Stage_88925_Desc = {
    Text = "Ich halte das Feuer, das du einst entfacht hast. \nDu hast mich einst geleitet, ich werde deine Augen sein und dich wieder ins Licht führen.\nDen Weg, den du gegangen bist, werde ich für dich weitergehen, alle rostigen Zäune werden vor diesem Feuer zusammenbrechen."
  },
  Stage_88925_Name = {
    Text = "Bote der Kerze·Wahnsinn"
  },
