  Stage_91019_Name = {
    Text = "Triumphpfad - Teil 6"
  },
  Stage_91088_Desc = {
    Text = "Sie sind Herr und Diener, Mörder und Opfer, Überreste desselben Trümmers. \nDem Hunger des Blutes folgend, begegnen sie sich unerwartet vor derselben Tür."
  },
  Stage_91088_Name = {
    Text = "Sklave und Sklavenhalter"
  },
  Stage_91091_Desc = {
    Text = "Wer sagt, dass die Glorie der Vergangenheit nicht zurückkehren kann?\nSieh her, verfluchte moderne Technologie! Die Kraft Roms wird am Ende über alles triumphieren!"
  },
  Stage_91091_Name = {
    Text = "Die Macht Roms"
  },
  Stage_94464_Desc = {
    Text = "Erwecker aus dem Aequor bringen die gewaltige Macht, die unter den Tiefen des Ozeans verborgen liegt, vor dich.\nKämpfe an ihrer Seite und lerne, die Kraft der Tentakel zu beherrschen."
  },
  Stage_94464_Name = {
    Text = "Berührung des Aequor"
  },
  Stage_94465_Desc = {
    Text = "Fleisch ist der Ursprung des Lebens und auch das Ende des Lebens. Aus dem Tod entsteht Leben—die aus reinem Fleisch geschmiedeten Erwecker verstehen dies am besten.\nKämpfe an ihrer Seite und lerne, die Kraft des Fleisches zu nutzen."
  },
  Stage_94465_Name = {
    Text = "Ausbreitung des Fleisches"
  },
  Stage_94466_Desc = {
    Text = "Die Erwecker, die das Ultra durchqueren, verstehen die Geheimnisse dieses Raumes nicht vollständig. An dem Tag, an dem du sie entschlüsselst, wirst du eine Macht erblicken, die dich in Erstaunen versetzen wird.\nKämpfe an ihrer Seite und lerne, wie man den Hyperraum im Kampf nutzt."
  },
  Stage_94466_Name = {
    Text = "Das Ultra-Reich"
  },
  Stage_94806_Desc = {
    Text = "Ein schöner Urlaubstag sollte nicht durch Rücksichtslosigkeit und Gewalt getrübt werden. Wenn es schon zum Kampf kommen muss, dann lieber auf dem Volleyballfeld!"
  },
  Stage_94806_Name = {
    Text = "Kulturduell"
  },
  Stage_94808_Desc = {
    Text = "Als Champion sollte man schließlich einige kleine Privilegien genießen dürfen."
  },
  Stage_94808_Name = {
    Text = "Champion und Chaoskampf"
  },
  Stage_94811_Desc = {
    Text = "Wer den ersten Platz erobern will, fällt niemals zweimal am selben Ort!"
  },
  Stage_94811_Name = {
    Text = "Entscheidungsschuss"
  },
  Stage_94817_Desc = {
    Text = "Menschen sind es gewohnt, Regeln zu verwenden, um die unvermeidliche Zunahme der Entropie zu kontrollieren. Tatsächlich hat jeder Mensch seine eigenen Prinzipien – und wenn dutzende dieser Prinzipien aufeinanderprallen, wird das endgültige Prinzip hier sein: kein Prinzip!"
  },
  Stage_94817_Name = {
    Text = "Paarungsprinzip"
  },
  Stage_94824_Desc = {
    Text = "Eine stille Nacht, sanfter Seewind, unter dem sanften Licht der Sterne – immer der richtige Moment, um einige geheimnisvolle Gedanken zu teilen."
  },
  Stage_94824_Name = {
    Text = "Nur der Nachtwind weiß es"
  },
  Stage_94832_Desc = {
    Text = "Sie weiß tief in ihrem Herzen: Alleiniger Mut kann keinen unbesiegbaren Sieg erringen – so war es in der Vergangenheit, und so ist es auch heute."
  },
  Stage_94832_Name = {
    Text = "knapper Sieg"
  },
  Stage_94837_Desc = {
    Text = "Wenn diese Freude in diesem Moment festgehalten werden könnte, wünschte ich, dass die Dauer dieses Speichers ewig wäre."
  },
  Stage_94837_Name = {Text = "Ein Foto"},
  Stage_94841_Desc = {
    Text = "Die Küste ist die Standardantwort auf Urlaubsfragen. Wer könnte bei dieser Hitze schon der Verlockung widerstehen, barfuß durch die kühlen Wellen zu laufen und sich unter einem Sonnenschirm vor der glühenden Sonne zu schützen? Warte... warum fällt die Sonne plötzlich herunter?!"
  },
  Stage_94841_Name = {
    Text = "Hitzewarnung"
  },
  Stage_94843_Desc = {
    Text = "Auf der aufregenden Bühne des Wettbewerbs hat jeder Teilnehmer die Möglichkeit, seine Qualitäten zu präsentieren ... Regisseur, schneide alle Szenen, die nicht gesendet werden dürfen."
  },
  Stage_94843_Name = {
    Text = "Los geht's! Halbfinale!"
  },
  Stage_95332_Desc = {
    Text = "Sobald du ihnen beitrittst, trittst du in einen Vertrag mit dem Todesschreiber ein. Genieße gut, was sie dir bringen, denn du weißt nicht, wann der Vertrag in Kraft tritt."
  },
  Stage_95332_Name = {
    Text = "Vertragsziel · Teil 6"
  },
  Stage_95333_Desc = {
    Text = "Sobald du ihnen beitrittst, trittst du in einen Vertrag mit dem Todesschreiber ein. Genieße gut, was sie dir bringen, denn du weißt nicht, wann der Vertrag vollzogen wird."
  },
  Stage_95333_Name = {
    Text = "Vertragsziel – Teil 5"
  },
  Stage_95334_Desc = {
