  Stage_97105_Name = {
    Text = "Höllenwandel - Teil 4"
  },
  Stage_97227_Desc = {
    Text = "Das Opfer ist da, das Blut fließt in Fülle. O höchster Herrscher des Universums, führe deinen gläubigen Diener in das ewige Reich!"
  },
  Stage_97227_Name = {Text = "Blutopfer"},
  Stage_97228_Desc = {
    Text = "Die schwarze Sonne ist gekommen, nicht wahr?"
  },
  Stage_97228_Name = {
    Text = "Schwarze Sonne"
  },
  Stage_97229_Desc = {
    Text = "Verrat geschah genau zum richtigen Zeitpunkt, “von jemandem verführt“, “keine andere Wahl gehabt“, “um zu überleben“ – welche perfekten Gründe für einen Verrat! \nSchade nur, er hat sich das falsche Ziel für den Verrat ausgesucht."
  },
  Stage_97229_Name = {
    Text = "Ton des Verrats"
  },
  Stage_97230_Desc = {
    Text = "Die Lösung des Rätsels wird enthüllt – hast du richtig geraten?\nFindest du es klischeehaft? Ich finde es ganz interessant, schließlich... ist es mir egal, ob es interessant ist oder nicht."
  },
  Stage_97230_Name = {
    Text = "Hintergründiger Schuldiger"
  },
  Stage_97231_Desc = {
    Text = "Wir vergessen keine einzige Wohltat und erinnern uns an jeden Hass. Dies ist der letzte Luxus, den wir uns in dieser grausamen Welt erlauben können."
  },
  Stage_97231_Name = {
    Text = "Nie vergessen"
  },
  Stage_97232_Desc = {
    Text = [[
Hebe deinen katernden Kopf und nimm dein schmutziges Glas. Vergiss alles von letzter Nacht, die neue Party steht bevor. 
 Mein Freund, willkommen in diesem expressionistischen Paradies.]]
  },
  Stage_97232_Name = {
    Text = "Bestienstil-Kneipe"
  },
  Stage_97233_Desc = {
    Text = "Als der letzte Tropfen Wein aus dem Glas fiel, ertönte der Schuss, der alles begrub."
