  Stage_97663_Name = {
    Text = "Vorübergehender Text · I"
  },
  Stage_97807_Desc = {
    Text = "Mutter, ein Zauberspruch, den die Menschen von der Geburt bis zum Tod murmeln. \n Kein Kind möchte erwachsen werden, kein Kind sehnt sich nicht nach dem liebevollen Arm seiner Mutter. \n Willst du das grausame Schicksal spielen und sie ein weiteres Mal aus der Umarmung ihrer Mutter reißen?"
  },
  Stage_97807_Name = {
    Text = "Perfekte Märchen·Wahnsinn"
  },
  Stage_97808_Desc = {
    Text = "Die schönen Worte entstehen oft aus Schmerz. \n Sie erkannte die Schönheit, als sie bereits die Tragödien wusste, die längst in den Schatten des Lebens verborgen waren. \n Oh Schönheit, Schönheit ist alles, was vergänglich und zerbrochen ist."
  },
  Stage_97808_Name = {
    Text = "Poetischer Garten·Teil 6"
  },
  Stage_97809_Desc = {
    Text = "Wenn dieser Moment der Freude eingefroren werden könnte, wünschte ich, dass die Dauer dieser Erinnerung ewig wäre."
  },
  Stage_97809_Name = {Text = "Ein Foto"},
  Stage_97810_Desc = {
    Text = "Schöne Worte entstehen oft aus Schmerz. \n Als sie die Schönheit erkannte, wusste sie bereits um die Tragödien, die längst gekommen und im Schatten des Lebens verborgen waren. \n Oh Schönheit, Schönheit ist alles Vergängliche und Zerbrochene."
  },
  Stage_97810_Name = {
    Text = "Poetischer Garten·Teil 2"
  },
  Stage_97811_Desc = {
    Text = "Sie hat ihre Ideale nie vergessen, selbst nachdem sie ihre Seele verloren hat. \n Diejenigen, die für die Wissenschaft gestorben sind, lebten einst leidenschaftlich für die Wissenschaft."
  },
  Stage_97811_Name = {
    Text = "Maschinen Traum·Wahnsinn"
  },
  Stage_97812_Desc = {
    Text = "Du schlenderst durch den vertrauten, aber fremden Campus und schaust dir alles an, das lebhaft und gewöhnlich ist. Wirst du darüber erfreut und fasziniert sein? Oder wirst du traurig sein, weil du all dies nie hattest?"
  },
  Stage_97812_Name = {
    Text = "Wiederbesuch der alten Stätte · Teil 5"
  },
  Stage_97813_Desc = {
    Text = "Mutter, ein Zauberspruch, den die Menschen vom Geburtsmoment bis zum Tod murmeln. \n Kein Kind möchte erwachsen werden, kein Kind sehnt sich nicht nach dem liebevollen Arm seiner Mutter. \n Willst du das grausame Schicksal spielen und sie erneut aus der Umarmung ihrer Mutter reißen?"
  },
  Stage_97813_Name = {
    Text = "Perfektes Märchen · Teil 2"
  },
  Stage_97814_Desc = {
    Text = "Wer den ersten Platz erobern will, fällt niemals zweimal am selben Ort!"
  },
  Stage_97814_Name = {
    Text = "Entscheidungsschuss"
  },
  Stage_97815_Desc = {
    Text = "Sie hat ihre Ideale nie vergessen, selbst nachdem sie ihre Seele verloren hat. \nDie Menschen, die durch die Wissenschaft gestorben sind, haben einst leidenschaftlich für die Wissenschaft gelebt."
  },
  Stage_97815_Name = {
    Text = "Mechanischer Traum · Teil 1"
  },
  Stage_97816_Desc = {
    Text = "Sie hat ihren Ideal nie vergessen, selbst nachdem sie ihre Seele verloren hat. \n Die Menschen, die für die Wissenschaft gestorben sind, haben einst leidenschaftlich für die Wissenschaft gelebt."
  },
  Stage_97816_Name = {
    Text = "Mechanischer Traum·Teil 4"
  },
  Stage_97817_Desc = {
    Text = "Die Sonne ist längst gestorben, und am Himmel bleibt nur ein verwitterter Leichnam zurück. \n Wie diese verfallene Welt, was bleibt in dem schweren Staub zurück, ist es das Leben oder die Illusion der letzten Aktivitäten des Lebens?"
  },
  Stage_97817_Name = {
    Text = "Konfrontation mit der Dunkelheit · Teil 6"
  },
  Stage_97818_Desc = {
    Text = "Du schlenderst durch den vertrauten, aber fremden Campus und beobachtest das lebhafte, aber gewöhnliche Treiben. Wirst du darüber erfreut und fasziniert sein? Oder wirst du traurig sein über das, was du nie gehabt hast?"
  },
  Stage_97818_Name = {
    Text = "Rückkehr an den alten Ort · Teil 3"
  },
  Stage_97819_Desc = {
    Text = "Du schlenderst durch den vertrauten, aber fremden Campus und siehst alles, was lebhaft und gewöhnlich ist. Bist du darüber erfreut und fasziniert? Oder bist du traurig über das, was du nie gehabt hast?"
  },
  Stage_97819_Name = {
    Text = "Rückkehr an den vertrauten Ort · Teil 1"
  },
  Stage_97820_Desc = {
    Text = "Mutter, ein Zauberspruch, den die Menschen von der Geburt bis zum Tod murmeln. \n Kein Kind möchte erwachsen werden, kein Kind sehnt sich nicht nach der liebevollen Umarmung seiner Mutter. \n Willst du das grausame Schicksal spielen und sie erneut aus den Armen ihrer Mutter reißen?"
  },
  Stage_97820_Name = {
    Text = "Perfekte Märchen·Teil 4"
  },
  Stage_97821_Desc = {
    Text = "Mutter, ein Zauberspruch, den die Menschen vom Geburts- bis zum Sterbemoment murmeln. \n Kein Kind möchte erwachsen werden, kein Kind sehnt sich nicht nach der liebevollen Umarmung seiner Mutter. \n Willst du das grausame Schicksal spielen und sie erneut aus dem Schoß der Mutter reißen?"
  },
  Stage_97821_Name = {
