  Stage_99731_Name = {
    Text = "Premium-Tier-Tierisches"
  },
  Stage_99732_Desc = {
    Text = "Egal wie man den Vögeln die Flügel stutzt, sie werden allmählich vergessen, wie man fliegt."
  },
  Stage_99732_Name = {
    Text = "Draußen vor dem engen Tor"
  },
  Stage_99733_Desc = {
    Text = "Zünde den schwarzen Docht an und widme alles Ihm; lass die Laterne ewig leuchten und alle Sünden der Welt reinigen."
  },
  Stage_99733_Name = {Text = "Opfergabe"}
